export default async function install(app){const FeatureLayer=await app.import("esri/layers/FeatureLayer");const source=new FeatureLayer({url:app.config.serviceUrl,outFields:["*"]});await source.load();const result=await source.queryFeatures({where:"1=1",outFields:["*"],returnGeometry:false});const byName=new Map(),pairs=new Map(),baseName=n=>String(n||"").replace(/\s*\[[^\]]+\]\s*$/,"").trim();for(const f of result.features){const a=f.attributes;byName.set(String(a.Name),a);if(a.Type==="PRI"&&(a.ESRI_split_pin==="L"||a.ESRI_split_pin==="R")){const key=baseName(a.Name);if(!pairs.has(key))pairs.set(key,{});pairs.get(key)[a.ESRI_split_pin]=a}}const palette={Green:"#2e8540",Amber:"#f5a623",Red:"#d64545",Blue:"#386cb0"},safe=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const dot=(value,label="")=>{const colour=palette[value]||"#707070",text=value||"No status";return `<span title="${safe(text)}" style="display:inline-flex;align-items:center;gap:5px;margin-right:10px;white-space:nowrap"><span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:${colour};border:1px solid rgba(0,0,0,.22)"></span>${label?`<span style="font-size:11px;color:#5b5b5b">${safe(label)}</span>`:""}</span>`};const row=(label,content)=>`<div style="display:grid;grid-template-columns:92px 1fr;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid #e5e5e5"><strong style="font-size:12px">${label}</strong><span>${content}</span></div>`,status=(a,mode,side)=>a?.[`${mode}_Headroom_RAG_${side}`];const popupFor=graphic=>({title:"{name}",outFields:["*"],content:[{type:"custom",creator:()=>{const attrs=graphic.attributes||{},name=String(attrs.name||""),pair=pairs.get(name),record=byName.get(name),box=document.createElement("div");let html=`<div style="font:13px/1.35 Arial,sans-serif;min-width:250px"><div style="margin-bottom:8px"><strong>${safe(attrs.typeLabel||"")}</strong></div>`;if(pair?.L&&pair?.R){html+=row("Demand",dot(status(pair.L,"Demand","PRI"),"1")+dot(status(pair.R,"Demand","PRI"),"2"))+row("Generation",dot(status(pair.L,"Generation","PRI"),"1")+dot(status(pair.R,"Generation","PRI"),"2"))+row("Fault level",dot(status(pair.L,"Fault","PRI"),"1")+dot(status(pair.R,"Fault","PRI"),"2"))}else if(record){const hasPri=Boolean(record.Voltage_Domain_PRI),hasBsp=Boolean(record.Voltage_Domain_BSP),ind=m=>`${hasPri?dot(status(record,m,"PRI"),hasBsp?"Primary":""):""}${hasBsp?dot(status(record,m,"BSP"),hasPri?"Bulk":""):""}`;html+=row("Demand",ind("Demand"))+row("Generation",ind("Generation"))+row("Fault level",ind("Fault"))}html+=`<div style="margin-top:10px"><button type="button" data-details style="width:100%;padding:8px 10px;border:1px solid #007ac2;background:#007ac2;color:white;border-radius:2px;cursor:pointer;font-weight:600">Additional information</button></div></div>`;box.innerHTML=html;box.querySelector("[data-details]").addEventListener("click",()=>document.dispatchEvent(new CustomEvent("capacity-show-attributes",{detail:{name}})));return box}}]});let handle=null,layerHandle=null;const apply=()=>{const layer=app.map.findLayerById(app.config.graphicsLayerId);if(!layer)return 0;for(const graphic of layer.graphics)graphic.popupTemplate=popupFor(graphic);return layer.graphics.length};const attach=()=>{handle?.remove?.();const layer=app.map.findLayerById(app.config.graphicsLayerId);if(layer?.graphics?.on){apply();handle=layer.graphics.on("change",()=>queueMicrotask(apply))}};attach();layerHandle=app.map.layers.on("change",attach);app.onCleanup(()=>{handle?.remove?.();layerHandle?.remove?.()});return{updatedPopups:apply(),detailsButton:true}}